//! SPDM cryptographic algorithm types.
//!
//! Algorithm bitmaps are typed: each family has its own `Unaligned`
//! newtype generated by [`def_flag_set_le!`] so handler code uses
//! named constants (e.g. `AeadAlgos::AES_256_GCM`) instead of magic
//! bit positions.

use zerocopy::{
    little_endian::{U16, U32},
    FromBytes, Immutable, IntoBytes, KnownLayout, Unaligned,
};

use crate::flag_macros::{def_flag_set_le, def_flag_set_u8};
use crate::{ReqRespCode, RequestBody, ResponseBody, WireError, WireReader, WireWriter};

// ---- typed algorithm bit-flag types ----------------------------------------

def_flag_set_u8! {
  /// MeasurementSpecification.
    pub struct MeasSpec {
        DMTF = 1 << 0,
    }
}

def_flag_set_u8! {
  /// OtherParamsSupport / OtherParamsSel (SPDM the corresponding table
  /// byte 7) — opaque-data-format negotiation introduced in v1.2.
    pub struct OtherParamSupport {
        OPAQUE_DATA_FMT1 = 1 << 1,
    /// SPDM 1.3 MultiKeyConn negotiation.
        MULTI_KEY_CONN = 1 << 4,
    }
}

def_flag_set_le! {
  /// MeasurementHashAlgo.
    pub struct MeasHashAlgos(U32: u32) {
        RAW_BIT = 1 << 0,
        SHA_256 = 1 << 1,
        SHA_384 = 1 << 2,
        SHA_512 = 1 << 3,
        SHA3_256 = 1 << 4,
        SHA3_384 = 1 << 5,
        SHA3_512 = 1 << 6,
        SM3_256 = 1 << 7,
    }
}

def_flag_set_le! {
  /// BaseAsymAlgo / BaseAsymSel.
    pub struct AsymAlgos(U32: u32) {
        RSASSA_2048 = 1 << 0,
        RSAPSS_2048 = 1 << 1,
        RSASSA_3072 = 1 << 2,
        RSAPSS_3072 = 1 << 3,
        ECDSA_ECC_NIST_P256 = 1 << 4,
        RSASSA_4096 = 1 << 5,
        RSAPSS_4096 = 1 << 6,
        ECDSA_ECC_NIST_P384 = 1 << 7,
        ECDSA_ECC_NIST_P521 = 1 << 8,
        SM2_ECC_SM2_P256 = 1 << 9,
        EDDSA_ED25519 = 1 << 10,
        EDDSA_ED448 = 1 << 11,
    }
}

def_flag_set_le! {
  /// SPDM 1.4 PQCAsymAlgo / PQCAsymSel bitmap.
    pub struct PqcAsymAlgos(U32: u32) {
        ML_DSA_44 = 1 << 0,
        ML_DSA_65 = 1 << 1,
        ML_DSA_87 = 1 << 2,
        SLH_DSA_SHA2_128S = 1 << 3,
        SLH_DSA_SHAKE_128S = 1 << 4,
        SLH_DSA_SHA2_128F = 1 << 5,
        SLH_DSA_SHAKE_128F = 1 << 6,
        SLH_DSA_SHA2_192S = 1 << 7,
        SLH_DSA_SHAKE_192S = 1 << 8,
        SLH_DSA_SHA2_192F = 1 << 9,
        SLH_DSA_SHAKE_192F = 1 << 10,
        SLH_DSA_SHA2_256S = 1 << 11,
        SLH_DSA_SHAKE_256S = 1 << 12,
        SLH_DSA_SHA2_256F = 1 << 13,
        SLH_DSA_SHAKE_256F = 1 << 14,
    }
}

def_flag_set_le! {
  /// BaseHashAlgo / BaseHashSel.
    pub struct HashAlgos(U32: u32) {
        SHA_256 = 1 << 0,
        SHA_384 = 1 << 1,
        SHA_512 = 1 << 2,
        SHA3_256 = 1 << 3,
        SHA3_384 = 1 << 4,
        SHA3_512 = 1 << 5,
        SM3_256 = 1 << 6,
    }
}

def_flag_set_le! {
  /// DHE.AlgSupported.
    pub struct DheAlgos(U16: u16) {
        FFDHE_2048 = 1 << 0,
        FFDHE_3072 = 1 << 1,
        FFDHE_4096 = 1 << 2,
        SECP_256_R1 = 1 << 3,
        SECP_384_R1 = 1 << 4,
        SECP_521_R1 = 1 << 5,
        SM2_P256 = 1 << 6,
    }
}

def_flag_set_le! {
  /// AEAD.AlgSupported.
    pub struct AeadAlgos(U16: u16) {
        AES_128_GCM = 1 << 0,
        AES_256_GCM = 1 << 1,
        CHACHA20_POLY1305 = 1 << 2,
        AEAD_SM4_GCM = 1 << 3,
    }
}

def_flag_set_le! {
  /// KeySchedule.AlgSupported.
    pub struct KeyScheduleAlgos(U16: u16) {
        SPDM = 1 << 0,
    }
}

// ---- AlgType discriminants -------------------------------------------------

/// `AlgType` byte values for AlgStruct entries.
pub mod alg_type {
    pub const DHE: u8 = 0x02;
    pub const AEAD: u8 = 0x03;
    pub const REQ_BASE_ASYM: u8 = 0x04;
    pub const KEY_SCHEDULE: u8 = 0x05;
    pub const REQ_PQC_ASYM_ALG: u8 = 0x06;
    pub const KEM_ALG: u8 = 0x07;
}

// ---- NEGOTIATE_ALGORITHMS request wire types -------------------------------

/// Fixed 30-byte prefix of the NEGOTIATE_ALGORITHMS request body
///. Followed by zero or more 4-byte
/// extended-asym entries, then extended-hash entries, then
/// [`AlgStructEntry`] entries.
#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Unaligned, Copy, Clone, Default)]
#[repr(C)]
pub struct NegotiateAlgorithmsReqBodyFixed {
    /// Param1: number of AlgStruct entries that follow.
    pub num_alg_struct: u8,
    /// Param2: Reserved.
    pub param2: u8,
    /// Total request length in bytes (including SPDM header).
    pub length: U16,
    pub measurement_spec: MeasSpec,
    pub other_param_support: OtherParamSupport,
    pub base_asym_algo: AsymAlgos,
    pub base_hash_algo: HashAlgos,
    /// PQC asymmetric algorithms offered by the requester in V1.4.
    /// Reserved and zero in earlier versions.
    pub pqc_asym_algo: PqcAsymAlgos,
    pub reserved1: [u8; 8],
    pub ext_asym_count: u8,
    pub ext_hash_count: u8,
    /// Byte 28: Reserved.
    pub reserved2: u8,
    /// Byte 29: MelSpecification (V1.3) / Reserved (V1.2).
    pub mel_spec_or_reserved: u8,
}

impl NegotiateAlgorithmsReqBodyFixed {
    pub const SIZE: usize = 30;
    /// Maximum total request length accepted by this responder.
    pub const MAX_REQUEST_LENGTH: u16 = 128;
}

const _: () = assert!(
    core::mem::size_of::<NegotiateAlgorithmsReqBodyFixed>()
        == NegotiateAlgorithmsReqBodyFixed::SIZE
);

/// Builder for a NEGOTIATE_ALGORITHMS request (requester side, v1.2+).
///
/// Emits the 30-byte fixed prefix followed by the `AlgStruct[]` entries. This
/// builder never sends extended (vendor) algorithms — `ext_asym_count` /
/// `ext_hash_count` are 0 and each `AlgStructEntry` uses `ExtAlgCount = 0`.
pub struct NegotiateAlgorithmsReq {
    pub measurement_spec: MeasSpec,
    pub other_param_support: OtherParamSupport,
    pub base_asym_algo: AsymAlgos,
    pub base_hash_algo: HashAlgos,
    /// PQC algorithms offered (V1.4). Must be empty for earlier versions, where
    /// the field is reserved.
    pub pqc_asym_algo: PqcAsymAlgos,
    /// AlgStruct entries to offer; `None` slots are skipped.
    pub alg_structs: [Option<AlgStructEntry>; MAX_ALG_STRUCT_ENTRIES],
}

impl NegotiateAlgorithmsReq {
    fn num_alg_struct(&self) -> u8 {
        self.alg_structs.iter().filter(|x| x.is_some()).count() as u8
    }
}

impl RequestBody for NegotiateAlgorithmsReq {
    const REQUEST_CODE: ReqRespCode = ReqRespCode::NEGOTIATE_ALGORITHMS;

    fn body_size(&self) -> usize {
        NegotiateAlgorithmsReqBodyFixed::SIZE
            + (self.num_alg_struct() as usize) * AlgStructEntry::SIZE
    }

    fn encode_body(&self, w: &mut WireWriter<'_>) -> Result<(), WireError> {
        let num = self.num_alg_struct();
        let length = (crate::SpdmMsgHdrPdu::SIZE + self.body_size()) as u16;
        w.write(&NegotiateAlgorithmsReqBodyFixed {
            num_alg_struct: num,
            param2: 0,
            length: U16::new(length),
            measurement_spec: self.measurement_spec,
            other_param_support: self.other_param_support,
            base_asym_algo: self.base_asym_algo,
            base_hash_algo: self.base_hash_algo,
            pqc_asym_algo: self.pqc_asym_algo,
            reserved1: [0; 8],
            ext_asym_count: 0,
            ext_hash_count: 0,
            reserved2: 0,
            mel_spec_or_reserved: 0,
        })?;
        for entry in self.alg_structs.iter().flatten() {
            w.write(entry)?;
        }
        Ok(())
    }
}

// ---- ALGORITHMS response wire types ----------------------------------------

/// Fixed-size prefix of the ALGORITHMS response body. Followed by
/// zero or more 4-byte AlgStruct entries.
#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Unaligned, Copy, Clone, Default)]
#[repr(C)]
pub struct AlgorithmsRspBodyFixed {
    pub num_alg_struct: u8,
    pub param2: u8,
    pub length: U16,
    pub measurement_spec_sel: MeasSpec,
    pub other_param_support: OtherParamSupport,
    pub meas_hash_algo: MeasHashAlgos,
    pub base_asym_sel: AsymAlgos,
    pub base_hash_sel: HashAlgos,
    /// Selected PQC asymmetric algorithm, valid from V1.4 onward and
    /// zero on earlier versions.
    ///
    /// A 1.4 connection selects exactly one signing algorithm, so this
    /// and `base_asym_sel` are mutually exclusive: when a PQC algorithm
    /// is selected, `base_asym_sel` is empty, and vice versa.
    pub pqc_asym_sel: PqcAsymAlgos,
    pub reserved3: [u8; 7],
    pub mel_specification_sel: u8,
    pub ext_asym_sel_count: u8,
    pub ext_hash_sel_count: u8,
    pub reserved4: [u8; 2],
}

impl AlgorithmsRspBodyFixed {
    pub const SIZE: usize = 34;
}

const _: () =
    assert!(core::mem::size_of::<AlgorithmsRspBodyFixed>() == AlgorithmsRspBodyFixed::SIZE);

/// 4-byte AlgStruct entry.
#[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Unaligned, Copy, Clone, Default)]
#[repr(C)]
pub struct AlgStructEntry {
    /// One of [`alg_type`] constants.
    pub alg_type: u8,
    /// `FixedAlgCount[3:0] | ExtAlgCount[7:4]`. We always emit
    /// `FixedAlgCount = 2` (one 16-bit AlgSupported bitmap, no
    /// external algs).
    pub alg_count_etc: u8,
    pub alg_supported: U16,
}

impl AlgStructEntry {
    pub const SIZE: usize = 4;
    pub const FIXED_ALG_COUNT_ETC: u8 = 0x20;

    /// Helper for a DHE selection.
    pub fn dhe(algos: DheAlgos) -> Self {
        Self {
            alg_type: alg_type::DHE,
            alg_count_etc: Self::FIXED_ALG_COUNT_ETC,
            alg_supported: U16::new(algos.into_bits()),
        }
    }
    /// Helper for an AEAD selection.
    pub fn aead(algos: AeadAlgos) -> Self {
        Self {
            alg_type: alg_type::AEAD,
            alg_count_etc: Self::FIXED_ALG_COUNT_ETC,
            alg_supported: U16::new(algos.into_bits()),
        }
    }
    /// Helper for a KeySchedule selection.
    pub fn key_schedule(algos: KeyScheduleAlgos) -> Self {
        Self {
            alg_type: alg_type::KEY_SCHEDULE,
            alg_count_etc: Self::FIXED_ALG_COUNT_ETC,
            alg_supported: U16::new(algos.into_bits()),
        }
    }
}

const _: () = assert!(core::mem::size_of::<AlgStructEntry>() == AlgStructEntry::SIZE);

/// Maximum AlgStruct entries the responder advertises (DHE, AEAD,
/// ReqBaseAsymAlg, KeySchedule).
pub const MAX_ALG_STRUCT_ENTRIES: usize = 4;

/// Builder for an ALGORITHMS response (v1.2+).
pub struct AlgorithmsRsp {
    pub measurement_spec_sel: MeasSpec,
    pub other_param_support: OtherParamSupport,
    pub meas_hash_algo: MeasHashAlgos,
    pub base_asym_sel: AsymAlgos,
    pub base_hash_sel: HashAlgos,
    pub pqc_asym_sel: PqcAsymAlgos,
    /// AlgStruct entries to advertise; `None` slots are skipped.
    pub alg_structs: [Option<AlgStructEntry>; MAX_ALG_STRUCT_ENTRIES],
}

impl AlgorithmsRsp {
    fn num_alg_struct(&self) -> u8 {
        self.alg_structs.iter().filter(|x| x.is_some()).count() as u8
    }
}

impl ResponseBody for AlgorithmsRsp {
    fn response_code(&self) -> ReqRespCode {
        ReqRespCode::ALGORITHMS
    }

    fn body_size(&self) -> usize {
        AlgorithmsRspBodyFixed::SIZE + (self.num_alg_struct() as usize) * AlgStructEntry::SIZE
    }

    fn encode_body(&self, w: &mut WireWriter<'_>) -> Result<(), WireError> {
        let num = self.num_alg_struct();
        let length = (crate::SpdmMsgHdrPdu::SIZE + self.body_size()) as u16;
        w.write(&AlgorithmsRspBodyFixed {
            num_alg_struct: num,
            param2: 0,
            length: U16::new(length),
            measurement_spec_sel: self.measurement_spec_sel,
            other_param_support: self.other_param_support,
            meas_hash_algo: self.meas_hash_algo,
            base_asym_sel: self.base_asym_sel,
            base_hash_sel: self.base_hash_sel,
            pqc_asym_sel: self.pqc_asym_sel,
            reserved3: [0; 7],
            mel_specification_sel: 0,
            ext_asym_sel_count: 0,
            ext_hash_sel_count: 0,
            reserved4: [0; 2],
        })?;
        for entry in self.alg_structs.iter().flatten() {
            w.write(entry)?;
        }
        Ok(())
    }
}

/// A parsed ALGORITHMS response (requester side): the responder's selected
/// algorithms plus the per-family AlgStruct selections.
#[derive(Clone, Copy)]
pub struct ParsedAlgorithmsRsp {
    pub measurement_spec_sel: MeasSpec,
    pub other_param_support: OtherParamSupport,
    pub meas_hash_algo: MeasHashAlgos,
    pub base_asym_sel: AsymAlgos,
    pub base_hash_sel: HashAlgos,
    /// PQC selection (V1.4); empty when a classical algorithm was selected.
    pub pqc_asym_sel: PqcAsymAlgos,
    /// DHE selection from the DHE AlgStruct, if present.
    pub dhe: DheAlgos,
    /// AEAD selection from the AEAD AlgStruct, if present.
    pub aead: AeadAlgos,
    /// KeySchedule selection from the KeySchedule AlgStruct, if present.
    pub key_schedule: KeyScheduleAlgos,
}

impl ParsedAlgorithmsRsp {
    /// Parse an ALGORITHMS response body (everything after the 2-byte SPDM
    /// common header). Extracts the fixed selections and the DHE/AEAD/
    /// KeySchedule AlgStruct entries; other AlgStruct types are ignored.
    pub fn parse(body: &[u8]) -> Result<Self, WireError> {
        let mut r = WireReader::new(body);
        let fixed: &AlgorithmsRspBodyFixed = r.read()?;

        let mut out = Self {
            measurement_spec_sel: fixed.measurement_spec_sel,
            other_param_support: fixed.other_param_support,
            meas_hash_algo: fixed.meas_hash_algo,
            base_asym_sel: fixed.base_asym_sel,
            base_hash_sel: fixed.base_hash_sel,
            pqc_asym_sel: fixed.pqc_asym_sel,
            dhe: DheAlgos::EMPTY,
            aead: AeadAlgos::EMPTY,
            key_schedule: KeyScheduleAlgos::EMPTY,
        };

        for _ in 0..fixed.num_alg_struct {
            let entry: &AlgStructEntry = r.read()?;
            let bits = entry.alg_supported.get();
            match entry.alg_type {
                alg_type::DHE => out.dhe = DheAlgos::from_bits(bits),
                alg_type::AEAD => out.aead = AeadAlgos::from_bits(bits),
                alg_type::KEY_SCHEDULE => out.key_schedule = KeyScheduleAlgos::from_bits(bits),
                _ => {}
            }
        }
        Ok(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::SpdmVersion;

    fn three_structs() -> [Option<AlgStructEntry>; MAX_ALG_STRUCT_ENTRIES] {
        // A `None` in the middle checks that empty slots are skipped on the wire.
        [
            Some(AlgStructEntry::dhe(DheAlgos::SECP_384_R1)),
            None,
            Some(AlgStructEntry::aead(AeadAlgos::AES_256_GCM)),
            Some(AlgStructEntry::key_schedule(KeyScheduleAlgos::SPDM)),
        ]
    }

    #[test]
    fn test_negotiate_algorithms_req_encode() {
        let req = NegotiateAlgorithmsReq {
            measurement_spec: MeasSpec::DMTF,
            other_param_support: OtherParamSupport::OPAQUE_DATA_FMT1,
            base_asym_algo: AsymAlgos::ECDSA_ECC_NIST_P384,
            base_hash_algo: HashAlgos::SHA_384,
            pqc_asym_algo: PqcAsymAlgos::EMPTY,
            alg_structs: three_structs(),
        };

        // Body = 30-byte fixed prefix + 3 AlgStruct entries * 4 bytes = 42.
        assert_eq!(req.body_size(), 42);

        // Buffer = 2-byte common header + 42-byte body = 44 bytes (0x2C).
        let mut buf = [0xFFu8; 44];
        let mut w = WireWriter::new(&mut buf);
        req.encode_with_header(SpdmVersion::V12, &mut w).unwrap();

        assert_eq!(
            buf,
            [
                0x12, 0xE3, // header: V1.2, NEGOTIATE_ALGORITHMS
                0x03, 0x00, // num_alg_struct = 3, param2
                0x2C, 0x00, // length = 44 (includes the common header)
                0x01, // measurement_spec = DMTF
                0x02, // other_param_support = OPAQUE_DATA_FMT1
                0x80, 0x00, 0x00, 0x00, // base_asym_algo = ECDSA P-384 (1 << 7)
                0x02, 0x00, 0x00, 0x00, // base_hash_algo = SHA-384 (1 << 1)
                0x00, 0x00, 0x00, 0x00, // pqc_asym_algo = none (classical only)
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // reserved1
                0x00, 0x00, // ext_asym_count, ext_hash_count
                0x00, 0x00, // reserved2, mel_spec
                0x02, 0x20, 0x10, 0x00, // DHE: FixedAlgCount=2, SECP_384_R1 (1 << 4)
                0x03, 0x20, 0x02, 0x00, // AEAD: AES_256_GCM (1 << 1)
                0x05, 0x20, 0x01, 0x00, // KeySchedule: SPDM (1 << 0)
            ]
        );
    }

    #[test]
    fn test_negotiate_algorithms_req_encodes_pqc_offer() {
        let req = NegotiateAlgorithmsReq {
            measurement_spec: MeasSpec::DMTF,
            other_param_support: OtherParamSupport::EMPTY,
            base_asym_algo: AsymAlgos::ECDSA_ECC_NIST_P384,
            base_hash_algo: HashAlgos::SHA_384,
            pqc_asym_algo: PqcAsymAlgos::ML_DSA_87,
            alg_structs: [None; MAX_ALG_STRUCT_ENTRIES],
        };
        let mut buf = [0u8; 64];
        let mut w = WireWriter::new(&mut buf);
        req.encode_with_header(SpdmVersion::V14, &mut w).unwrap();
        // 2-byte header + body offset 14: PqcAsymAlgo, little-endian ML_DSA_87 = 1 << 2.
        assert_eq!(&buf[16..20], &[0x04, 0, 0, 0]);
    }

    #[test]
    fn test_negotiate_algorithms_req_no_alg_structs() {
        let req = NegotiateAlgorithmsReq {
            measurement_spec: MeasSpec::DMTF,
            other_param_support: OtherParamSupport::EMPTY,
            base_asym_algo: AsymAlgos::ECDSA_ECC_NIST_P256,
            base_hash_algo: HashAlgos::SHA_256,
            pqc_asym_algo: PqcAsymAlgos::EMPTY,
            alg_structs: [None; MAX_ALG_STRUCT_ENTRIES],
        };
        // Body = 30 + 0 entries; wire = 2 + 30 = 32 bytes (0x20).
        assert_eq!(req.body_size(), 30);
        let mut buf = [0u8; 32];
        let mut w = WireWriter::new(&mut buf);
        req.encode_with_header(SpdmVersion::V12, &mut w).unwrap();
        assert_eq!(buf[2], 0); // num_alg_struct
        assert_eq!(&buf[4..6], &[0x20, 0x00]); // length = 32
    }

    #[test]
    fn test_negotiate_algorithms_req_buffer_too_small() {
        let req = NegotiateAlgorithmsReq {
            measurement_spec: MeasSpec::DMTF,
            other_param_support: OtherParamSupport::EMPTY,
            base_asym_algo: AsymAlgos::ECDSA_ECC_NIST_P384,
            base_hash_algo: HashAlgos::SHA_384,
            pqc_asym_algo: PqcAsymAlgos::EMPTY,
            alg_structs: three_structs(),
        };
        // Needs 44 bytes; 43 is one short, so the last AlgStruct write fails.
        let mut buf = [0u8; 43];
        let mut w = WireWriter::new(&mut buf);
        assert!(req.encode_with_header(SpdmVersion::V12, &mut w).is_err());
    }

    fn rsp_p384_sha384() -> AlgorithmsRsp {
        AlgorithmsRsp {
            measurement_spec_sel: MeasSpec::DMTF,
            other_param_support: OtherParamSupport::OPAQUE_DATA_FMT1,
            meas_hash_algo: MeasHashAlgos::SHA_384,
            base_asym_sel: AsymAlgos::ECDSA_ECC_NIST_P384,
            base_hash_sel: HashAlgos::SHA_384,
            pqc_asym_sel: PqcAsymAlgos::EMPTY,
            alg_structs: three_structs(),
        }
    }

    #[test]
    fn test_algorithms_rsp_encode_and_parse() {
        let rsp = rsp_p384_sha384();

        // Body = 34-byte fixed prefix + 3 entries * 4 bytes = 46.
        assert_eq!(rsp.body_size(), 46);

        // Buffer = 2-byte common header + 46-byte body = 48 bytes (0x30).
        let mut buf = [0xFFu8; 48];
        let mut w = WireWriter::new(&mut buf);
        rsp.encode_with_header(SpdmVersion::V12, &mut w).unwrap();

        assert_eq!(
            buf,
            [
                0x12, 0x63, // header: V1.2, ALGORITHMS
                0x03, 0x00, // num_alg_struct = 3, param2
                0x30, 0x00, // length = 48 (includes the common header)
                0x01, // measurement_spec_sel = DMTF
                0x02, // other_param_support = OPAQUE_DATA_FMT1
                0x04, 0x00, 0x00, 0x00, // meas_hash_algo = SHA-384 (1 << 2)
                0x80, 0x00, 0x00, 0x00, // base_asym_sel = ECDSA P-384 (1 << 7)
                0x02, 0x00, 0x00, 0x00, // base_hash_sel = SHA-384 (1 << 1)
                0x00, 0x00, 0x00, 0x00, // pqc_asym_sel = none
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // reserved3 (7)
                0x00, 0x00, 0x00, // mel_spec_sel, ext_asym_sel_count, ext_hash_sel_count
                0x00, 0x00, // reserved4
                0x02, 0x20, 0x10, 0x00, // DHE: SECP_384_R1
                0x03, 0x20, 0x02, 0x00, // AEAD: AES_256_GCM
                0x05, 0x20, 0x01, 0x00, // KeySchedule: SPDM
            ]
        );

        let parsed = ParsedAlgorithmsRsp::parse(&buf[2..]).unwrap();
        assert_eq!(
            parsed.measurement_spec_sel.into_bits(),
            MeasSpec::DMTF.into_bits()
        );
        assert_eq!(
            parsed.other_param_support.into_bits(),
            OtherParamSupport::OPAQUE_DATA_FMT1.into_bits()
        );
        assert_eq!(
            parsed.meas_hash_algo.into_bits(),
            MeasHashAlgos::SHA_384.into_bits()
        );
        assert_eq!(
            parsed.base_asym_sel.into_bits(),
            AsymAlgos::ECDSA_ECC_NIST_P384.into_bits()
        );
        assert_eq!(
            parsed.base_hash_sel.into_bits(),
            HashAlgos::SHA_384.into_bits()
        );
        assert_eq!(parsed.dhe.into_bits(), DheAlgos::SECP_384_R1.into_bits());
        assert_eq!(parsed.aead.into_bits(), AeadAlgos::AES_256_GCM.into_bits());
        assert_eq!(
            parsed.key_schedule.into_bits(),
            KeyScheduleAlgos::SPDM.into_bits()
        );
    }

    #[test]
    fn test_algorithms_rsp_pqc_selection_is_exclusive_with_classical() {
        // V1.4: exactly one signing algorithm is selected, so choosing ML-DSA-87
        // leaves base_asym_sel empty.
        let rsp = AlgorithmsRsp {
            base_asym_sel: AsymAlgos::EMPTY,
            pqc_asym_sel: PqcAsymAlgos::ML_DSA_87,
            ..rsp_p384_sha384()
        };
        let mut buf = [0u8; 48];
        let mut w = WireWriter::new(&mut buf);
        rsp.encode_with_header(SpdmVersion::V14, &mut w).unwrap();

        // Body offsets (buf offset = body offset + 2): base_asym_sel 10..14,
        // pqc_asym_sel 18..22.
        assert_eq!(&buf[12..16], &[0x00, 0x00, 0x00, 0x00]);
        assert_eq!(&buf[20..24], &[0x04, 0x00, 0x00, 0x00]); // ML_DSA_87 = 1 << 2

        let parsed = ParsedAlgorithmsRsp::parse(&buf[2..]).unwrap();
        assert!(parsed.base_asym_sel.is_empty());
    }

    #[test]
    fn test_parse_algorithms_rejects_short_fixed_prefix() {
        // Fixed prefix is 34 bytes; 33 is one short.
        assert!(ParsedAlgorithmsRsp::parse(&[0u8; 33]).is_err());
        assert!(ParsedAlgorithmsRsp::parse(&[]).is_err());
    }

    #[test]
    fn test_parse_algorithms_rejects_truncated_alg_structs() {
        // Fixed prefix claims 2 entries (8 bytes) but only 1 (4 bytes) follows.
        let mut body = [0u8; 34 + 4];
        body[0] = 2;
        body[34..].copy_from_slice(&[0x02, 0x20, 0x10, 0x00]);
        assert!(ParsedAlgorithmsRsp::parse(&body).is_err());

        // A partial entry (3 of 4 bytes) is also rejected.
        let mut partial = [0u8; 34 + 3];
        partial[0] = 1;
        assert!(ParsedAlgorithmsRsp::parse(&partial).is_err());
    }

    #[test]
    fn test_parse_algorithms_ignores_unknown_alg_struct_types() {
        // One ReqBaseAsymAlg (0x04) entry: parsed past, but ParsedAlgorithmsRsp
        // has no field for it, so DHE/AEAD/KeySchedule stay empty.
        let mut body = [0u8; 34 + 4];
        body[0] = 1;
        body[34..].copy_from_slice(&[alg_type::REQ_BASE_ASYM, 0x20, 0x80, 0x00]);
        let parsed = ParsedAlgorithmsRsp::parse(&body).unwrap();
        assert!(parsed.dhe.is_empty());
        assert!(parsed.aead.is_empty());
        assert!(parsed.key_schedule.is_empty());
    }

    #[test]
    fn test_alg_struct_helpers_wire_layout() {
        // type, FixedAlgCount=2 in the high nibble (0x20), AlgSupported LE.
        assert_eq!(
            AlgStructEntry::dhe(DheAlgos::SECP_256_R1).as_bytes(),
            &[0x02, 0x20, 0x08, 0x00] // SECP_256_R1 = 1 << 3
        );
        assert_eq!(
            AlgStructEntry::aead(AeadAlgos::CHACHA20_POLY1305).as_bytes(),
            &[0x03, 0x20, 0x04, 0x00] // CHACHA20_POLY1305 = 1 << 2
        );
        assert_eq!(
            AlgStructEntry::key_schedule(KeyScheduleAlgos::SPDM).as_bytes(),
            &[0x05, 0x20, 0x01, 0x00]
        );
    }
}
